SELECT COUNT(DISTINCT m.match_id) AS partidas_sem_barao
FROM matches m
WHERE NOT EXISTS (
  SELECT 1 FROM teams t
  WHERE t.match_id = m.match_id AND t.barons > 0
);

SELECT AVG(t.towers) AS media_torres_vencedoras
FROM teams t
WHERE t.win = true;

SELECT MAX(total_kills) AS maior_quantidade_eliminacoes
FROM (
  SELECT match_id, team_id, SUM(kills) AS total_kills
  FROM participants
  GROUP BY match_id, team_id
) AS team_kills;

SELECT AVG(barons) AS media_barons_vencedoras
FROM teams
WHERE win = true;

SELECT MAX(ABS(gold_diff)) AS maior_diferenca_ouro
FROM (
  SELECT match_id, ABS(
    (SELECT SUM(gold_earned) FROM participants WHERE match_id = m.match_id AND team_id = 100) -
    (SELECT SUM(gold_earned) FROM participants WHERE match_id = m.match_id AND team_id = 200)
  ) AS gold_diff
  FROM matches m
) subq;
